import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { ROOT } from "../../evidence/lib";
import { BOWLER_RUNS, LEGAL, REGULATION, YEAR, derived, dp, floor, pearsonOf, range, type Row } from "../core";
